// TestVerifyGroth16_MsgCountProof_RejectsTamperedPublicInputs — geçerli bir
// proof'un public input'ları (min_count) sonradan değiştirilirse (Groth16'nın
// public input'lara bağlı olması gerektiği için) doğrulama reddetmeli.
func TestVerifyGroth16_MsgCountProof_RejectsTamperedPublicInputs(t *testing.T) {
	if err := LoadVerificationKeys("./keys"); err != nil {
		t.Fatalf("load vkeys: %v", err)
	}

	smokePath := filepath.Join("..", "..", "..", "circuits", "test", "msg_count_proof_smoke_proof.json")
	data, err := os.ReadFile(smokePath)
	if err != nil {
		t.Skip("msg_count_proof_smoke_proof.json not found")
	}

	var payload struct {
		ProofJSON    string   `json:"proof_json"`
		CircuitID    string   `json:"circuit_id"`
		PublicInputs []string `json:"public_inputs"`
	}
	if err := json.Unmarshal(data, &payload); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}

	// public_inputs sırası circuit'teki {public [min_count, epoch, count_commitment]}
	// sırası — min_count ilk eleman.
	if len(payload.PublicInputs) == 0 {
		t.Fatal("expected at least 1 public input (min_count)")
	}
	payload.PublicInputs[0] = "999999"

	err = VerifyGroth16(CircuitID(payload.CircuitID), []byte(payload.ProofJSON), payload.PublicInputs)
	if err == nil {
		t.Fatal("expected verification to fail for tampered min_count, got nil")
	}
	t.Logf("✓ tampered min_count correctly rejected: %v", err)
}

